/* From Uiverse.io by TheAbieza - Tags: flat design, loader, github, rotate, animated, vscode, music, box-shadow */
.__UIV_SCOPE__ .container {
  width: 175px;
  height: 175px;
  background-color: #ABC4AA;
  border-radius: 10px;
  position: relative;
  box-shadow: 5px 5px 0 0 #675D50;
}

.__UIV_SCOPE__ .plate {
  width: fit-content;
}

.__UIV_SCOPE__ .plate .black,
.__UIV_SCOPE__ .plate .white,
.__UIV_SCOPE__ .plate .center,
.__UIV_SCOPE__ .plate .border {
  border-radius: 100%;
}

.__UIV_SCOPE__ .container,
.__UIV_SCOPE__ .plate .black,
.__UIV_SCOPE__ .plate .white,
.__UIV_SCOPE__ .plate .border {
  display: flex;
  align-items: center;
  justify-content: center;
}

.__UIV_SCOPE__ .plate .black {
  width: 150px;
  height: 150px;
  background-color: #675D50;
  animation: rotation 2s infinite linear;
}

@keyframes rotation {
  from {
    transform: rotate(0deg);
  }

  to {
    transform: rotate(359deg);
  }
}

.__UIV_SCOPE__ .plate .white {
  width: 70px;
  height: 70px;
  background-color: #F3DEBA;
}

.__UIV_SCOPE__ .plate .center {
  width: 20px;
  height: 20px;
  background-color: #675D50;
}

.__UIV_SCOPE__ .plate .border {
  width: 111px;
  height: 111px;
  border-top: 3px solid #F3DEBA;
  border-bottom: 3px solid #F3DEBA;
  border-left: 3px solid #675D50;
  border-right: 3px solid #675D50;
}

.__UIV_SCOPE__ .player {
  display: flex;
  align-items: center;
  justify-content: center;
  flex-direction: column;
  width: fit-content;
  position: absolute;
  bottom: 0;
  right: 0;
  margin-bottom: 8px;
  margin-right: 8px;
  rotate: -45deg;
}

.__UIV_SCOPE__ .player .circ {
  width: 25px;
  height: 25px;
  background-color: #F3DEBA;
  border-radius: 100%;
  z-index: 1;
}

.__UIV_SCOPE__ .player .rect {
  width: 10px;
  height: 55px;
  background-color: #F3DEBA;
  position: absolute;
  bottom: 0;
  margin-bottom: 5px;
}
